export function run({ anthropic }) {
  let raw = "";
  try {
    raw = anthropic.content[0].text;
  } catch (e) {
    raw = typeof anthropic === "string" ? anthropic : JSON.stringify(anthropic, null, 2);
  }
  const match = raw.match(/\{[\s\S]*\}/);
  if (!match) throw new Error("No JSON object found in model response");
  const data = JSON.parse(match[0]);
  const date = new Date().toISOString().slice(0, 10);
  const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);
  const rows = [
    {
      date,
      platform: "LinkedIn",
      draft: (data.linkedin && data.linkedin.text) || "",
      score: num(data.scores && data.scores.linkedin && data.scores.linkedin.score),
      status: "Pending"
    },
    {
      date,
      platform: "X",
      draft: Array.isArray(data.x && data.x.tweets) ? data.x.tweets.join("\n\n\u2014 ") : "",
      score: num(data.scores && data.scores.x && data.scores.x.score),
      status: "Pending"
    },
    {
      date,
      platform: "Blog",
      draft:
        ((data.blog && data.blog.seoTitle) || "") + "\n\n" + ((data.blog && data.blog.intro) || ""),
      score: num(data.scores && data.scores.blog && data.scores.blog.score),
      status: "Pending"
    }
  ];
  return rows;
}
